// setting up truncated message html fotter function
char* xmoz =
    MimeHeaders_get(msg->hdrs, HEADER_X_MOZILLA_STATUS, false, false);
if (xmoz) {
  uint32_t flags = 0;
  char dummy = 0;
  if (sscanf(xmoz, " %x %c", &flags, &dummy) == 1 &&
      flags & nsMsgMessageFlags::Partial) {
    obj->options->html_closure =
        MimeClosure(MimeClosure::isMimeMessage, obj);
    obj->options->generate_footer_html_fn =
        MimeMessage_partial_message_html;
  }
  PR_FREEIF(xmoz);

static char* MimeMessage_partial_message_html(const char* data,
                                              MimeClosure closure,
                                              MimeHeaders* headers) {
  MimeMessage* msg = closure.AsMimeMessage();
  if (!msg) {
    return nullptr;
  }

MimeMessage* MimeClosure::AsMimeMessage() {
  PR_ASSERT(mType == isMimeMessage);
  return (mType == isMimeMessage) ? static_cast<MimeMessage*>(mClosure)
                                  : nullptr;
}
